package android.widget;
public class EdgeEffect { private boolean finished=true; public EdgeEffect(android.content.Context c) {} public EdgeEffect(android.content.Context c,android.util.AttributeSet a) {} public void setSize(int w,int h) {} public boolean isFinished() { return finished; } public void finish() { finished=true; } public void onPull(float delta) { finished=false; } public void onPull(float delta,float displacement) { finished=false; } public float onPullDistance(float delta,float displacement) { onPull(delta,displacement); return delta; } public float getDistance() { return 0; } public void onRelease() { finished=true; } public void onAbsorb(int velocity) { finished=false; } public boolean draw(android.graphics.Canvas canvas) { return false; } public void setColor(int color) {} public int getColor() { return 0; } }
